                    .put("spaceId", spaceIdFromKey(space))
                    .put("status", "current")
                    .put("title", title)
                    .put("parentId", parentId)
                    .put("body", new JSONObject()
                            .put("representation", "storage")
                            .put("value", body)).toString());
            return new Content(content.post());
