        String body,
        @MCPParam(name = "space", description = "The space key where to create the page", required = true, example = "PROJ")
        String space
    ) throws IOException {
        if (isApiV2()) {
            // Confluence v2 API: POST /wiki/api/v2/pages. Spaces are addressed by
