  /// Builds the v2 page creation payload (Java `createPage` v2 branch).
  Future<Map<String, dynamic>> _pagePayloadV2(
    String spaceKey,
    String title,
    String body,
    String? parentId,
  ) async {
    final spaceId = await spaceIdFromKey(spaceKey);
    return {
      'spaceId': spaceId,
      'status': 'current',
      'title': title,
      if (parentId != null) 'parentId': parentId,
